const R2D=180/Math.PI,D2R=Math.PI/180;
const my=lat=>-Math.log(Math.tan(Math.PI/4+lat*D2R/2))*R2D;
const ilat=y=>(2*Math.atan(Math.exp(-y/R2D))-Math.PI/2)*R2D;
const dec=r=>{let x=0,y=0,o=[];for(let i=0;i<r.length;i+=2){x+=r[i];y+=r[i+1];o.push([x/200,my(y/200)])}return o};
const toPath=(rings,p=new Path2D())=>{rings.forEach(r=>{r.forEach(([x,y],i)=>i?p.lineTo(x,y):p.moveTo(x,y));p.closePath()});return p};
const indiaR=GEO.india.map(dec),statesR=GEO.states.map(dec),nbR=GEO.nb.flatMap(n=>n.r.map(dec));
const P_IN=toPath(indiaR),P_ST=toPath(statesR),P_NB=toPath(nbR),P_LAND=toPath(nbR,toPath(indiaR));
function hav(a,b,c,d){const p=Math.sin((c-a)*D2R/2)**2+Math.cos(a*D2R)*Math.cos(c*D2R)*Math.sin((d-b)*D2R/2)**2;return 12742*Math.asin(Math.sqrt(p))}
function brg(a,b,c,d){const y=Math.sin((d-b)*D2R)*Math.cos(c*D2R),x=Math.cos(a*D2R)*Math.sin(c*D2R)-Math.sin(a*D2R)*Math.cos(c*D2R)*Math.cos((d-b)*D2R);return (Math.atan2(y,x)*R2D+360)%360}
