  const n=Math.min(160,Math.round(4+p*9)),sig=(3+Math.sqrt(p)*7)/105;
  for(let i=0;i<n;i++){const g=Math.abs(gauss());LIGHTS.push({x:lon+gauss()*sig,y:my(lat+gauss()*sig),a:(.12+rand()*.35)*(1.2-Math.min(1,g/3)),r:.5+rand()*1.2})}
