for(let i=0;i<4200&&LIGHTS.length<9000;i++){const lon=68+rand()*29.5,lat=6.5+rand()*30.5;const y=my(lat);if(!inIndia(lon,y)||rand()>density(lon,lat))continue;LIGHTS.push({x:lon,y,a:.08+rand()*.28,r:.4+rand()*.9})}
