  const og=c.createRadialGradient(W*.55,H*.45,0,W*.55,H*.45,Math.max(W,H)*.8);og.addColorStop(0,'#0b1218');og.addColorStop(1,'#04070a');c.fillStyle=og;c.fillRect(0,0,W,H);
  const T=[DPR*view.s,0,0,DPR*view.s,DPR*(W/2-view.cx*view.s),DPR*(H/2-view.cy*view.s)];
  c.setTransform(...T);const px=1/view.s;
