  for(let lo=60;lo<=100;lo+=5){c.moveTo(lo,my(40));c.lineTo(lo,my(2))}for(let la=5;la<=40;la+=5){c.moveTo(58,my(la));c.lineTo(102,my(la))}c.stroke();
