  c.fillStyle='rgba(4,6,9,.5)';c.fill(P_NB);
  // borders
  c.strokeStyle='rgba(236,229,216,.10)';c.lineWidth=.8*px;c.stroke(P_ST);
  c.strokeStyle='rgba(236,229,216,.10)';c.lineWidth=.8*px;c.stroke(P_NB);
  c.strokeStyle='rgba(210,173,100,.45)';c.lineWidth=1.1*px;c.stroke(P_IN);
  // lights
